) as v(legado_id, ticket, parte, valor_nota, valor, criado_em, rateio,
        legado_caminho, conta, loja_numero, loja_nome)
left join chamados c on c.numero = v.ticket::int
left join lateral (
  select u2.id from unidades u2 where u2.no_escopo and (
        (v.loja_numero::int between 1 and 99 and u2.nome ~* ('^loja 0*' || v.loja_numero || ' *-'))
     or (v.loja_numero::int >= 100 and upper(u2.nome) = upper(v.loja_nome))
     or (v.loja_numero is null and upper(u2.nome) like '%' || upper(v.loja_nome) || '%'))
   limit 1) u on true
on conflict (cliente_id, legado_id) where legado_id is not null do nothing;

commit;
